// Assets embedded as base64 so the PDF route never touches the filesystem —
// files under public/ are served statically but aren't reliably present in the
// serverless bundle at runtime.
//
// SIGNATURE_PNG is Oscar Garcia's signature, background removed to transparent.
// LOGO_PNG is the Ammex navy wordmark (no lines), from the branding project.
// HERITAGE_PNG is the heritage mark — crossed US/Mexico flags over the bridge —
// rasterised from the navy SVG, since pdf-lib embeds PNG rather than SVG.

export const SIGNATURE_PNG = "";

export const LOGO_PNG = "";

export const HERITAGE_PNG = "";
